    const top_k = ctrl.data.top_k;
    const cross_languages = ctrl.data.cross_languages;
    const use_kg = ctrl.data.use_kg;
    const n_rerank_eq = ctrl.data.n_rerank_eq;
    const n_pageindex_eq = ctrl.data.n_pageindex_eq;
    const query = ctrl.data.query;
    view.params.similarity_threshold = similarity_threshold
    view.params.keyword_similarity_weight = keyword_similarity_weight
    view.params.top_k = top_k
    view.params.cross_languages = cross_languages
